/// An assertion. It points at the exact bytes that support it and/or at the
/// other claims it rests on (`supports`), which is what makes the graph a DAG
/// of reasoning rather than a list of quotes.
///
/// `witness` says who or what proposed the claim, e.g. `human:sloane` or
/// `llm:<model> prompt=sha256:<digest of the prompt file>`. A claim from an
/// LLM is testimony: the verifier proves its quotes exist, not that the
/// statement follows from them. That judgment stays with people.
#[derive(Serialize, Clone, Debug)]
pub struct Claim {
    pub kind: &'static str,
    pub statement: String,
    pub witness: String,
    pub evidence: Vec<Evidence>,
    pub supports: Vec<Link>,
}

impl Claim {
    pub const KIND: &'static str = "claim";
    pub fn new(statement: &str, witness: &str, mut evidence: Vec<Evidence>, mut supports: Vec<Link>) -> Self {
        evidence.sort();
        evidence.dedup();
        supports.sort();
        supports.dedup();
        Claim { kind: Self::KIND, statement: statement.into(), witness: witness.into(), evidence, supports }
    }
}

