/// SHA-256 digests of the regular files directly in `<repo>/prompts/`.
/// A missing directory is an empty set; symlinks are not followed.
fn prompt_file_digests(repo_root: &Path) -> std::result::Result<BTreeSet<String>, String> {
    let dir = repo_root.join("prompts");
    let mut set = BTreeSet::new();
    let entries = match fs::read_dir(&dir) {
        Ok(e) => e,
        Err(e) if e.kind() == std::io::ErrorKind::NotFound => return Ok(set),
        Err(e) => return Err(format!("prompts/: cannot read: {e}")),
    };
    for entry in entries {
        let entry = entry.map_err(|e| format!("prompts/: cannot read: {e}"))?;
        let meta = fs::symlink_metadata(entry.path()).map_err(|e| format!("prompts/: cannot read: {e}"))?;
        if !meta.is_file() {
            continue;
        }
        let bytes = fs::read(entry.path()).map_err(|e| format!("prompts/: cannot read: {e}"))?;
        set.insert(crate::sha256::hex(&crate::sha256::digest(&bytes)));
    }
    Ok(set)
}

