/// Evidence for the unique whole-word occurrence of `quote` inside an
/// artifact's bytes. A hit counts only where the quote does not start or
/// end inside a word: if its first (last) character is a letter or digit,
/// the character before (after) it must not be one. So "nnu" is not found
/// in "annually", and "cat" in "cat concat" is unique.
pub fn evidence_for_quote(&self, artifact_id: &str, bytes: &[u8], quote: &[u8]) -> Result<Evidence> {
    if quote.is_empty() {
        return Err(Error::Invalid("empty quote".into()));
    }
    let raw: Vec<usize> = bytes.windows(quote.len()).enumerate().filter(|(_, w)| *w == quote).map(|(i, _)| i).collect();
    if raw.is_empty() {
        return Err(Error::Invalid("quote not found in artifact".into()));
    }
    let first_word = first_char(quote).is_some_and(char::is_alphanumeric);
    let last_word = last_char(quote).is_some_and(char::is_alphanumeric);
    let whole: Vec<usize> = raw
        .into_iter()
        .filter(|&i| {
            let before_ok = !first_word || !last_char(&bytes[..i]).is_some_and(char::is_alphanumeric);
            let after_ok = !last_word || !first_char(&bytes[i + quote.len()..]).is_some_and(char::is_alphanumeric);
            before_ok && after_ok
        })
        .collect();
    let start = match whole[..] {
        [] => return Err(Error::Invalid("quote occurs only inside a word; quote whole words".into())),
        [s] => s,
        _ => return Err(Error::Invalid("quote occurs more than once; make it unique".into())),
    };

