/// The first character of `b` if it starts with valid UTF-8, else None.
fn first_char(b: &[u8]) -> Option<char> {
    let n = b.len().min(4);
    (1..=n).find_map(|k| std::str::from_utf8(&b[..k]).ok()).and_then(|s| s.chars().next())
}

/// The last character of `b` if it ends with valid UTF-8, else None.
fn last_char(b: &[u8]) -> Option<char> {
    let n = b.len().min(4);
    (1..=n).find_map(|k| std::str::from_utf8(&b[b.len() - k..]).ok()).and_then(|s| s.chars().next_back())
}
