/// Witness kinds a claim may name. Anything else, in any other spelling, is
/// refused: a check that compares one spelling is bypassed by another.
pub const WITNESS_KINDS: [&str; 5] = ["human", "llm", "org", "doi", "arxiv"];

/// A witness is `<kind>:<id>` with `kind` from [`WITNESS_KINDS`] and a
/// non-empty id, optionally followed by space-separated detail. An `llm`
/// witness is testimony that can only be reproduced from its prompt, so it
/// must carry exactly one `prompt=` token: `prompt=sha256:<digest of a file
/// in prompts/>`, or `prompt=unrecorded`, said plainly.
fn check_witness(witness: &str, prompts: &std::result::Result<BTreeSet<String>, String>) -> std::result::Result<(), String> {
    let head = witness.split(' ').next().unwrap_or("");
    let Some((kind, id)) = head.split_once(':') else {
        return Err(format!("witness must be <kind>:<id> with kind one of {}: {witness:?}", WITNESS_KINDS.join(", ")));
    };
    if !WITNESS_KINDS.contains(&kind) || id.is_empty() {
        return Err(format!("witness must be <kind>:<id> with kind one of {}: {witness:?}", WITNESS_KINDS.join(", ")));
    }
    if kind != "llm" {
        return Ok(());
    }
    let need = "an llm witness must name exactly one prompt=: prompt=sha256:<digest of a file in prompts/> or prompt=unrecorded";
    let found: Vec<&str> = witness.split_whitespace().filter_map(|t| t.strip_prefix("prompt=")).collect();
    let [prompt] = found[..] else {
        return Err(format!("{need}: {witness:?}"));
    };
    if prompt == "unrecorded" {
        return Ok(());
    }
    let Some(hex) = prompt.strip_prefix("sha256:").filter(|h| crate::is_lower_hex(h, 64)) else {
        return Err(format!("{need}: {witness:?}"));
    };
    match prompts {
        Err(e) => Err(e.clone()),
        Ok(set) if set.contains(hex) => Ok(()),
        Ok(_) => Err(format!("prompt=sha256:{hex} names no file in prompts/")),
    }
}
