#[test]
fn coverage_follows_claims_and_reports_gaps_longest_first() {
    let (_d, s) = store();
    let doc = b"one two three\nfour five six\nseven";
    let (art, _) = s.ingest(doc, "d.txt", "text/plain").unwrap();
    let (other, _) = s.ingest(b"elsewhere", "e.txt", "text/plain").unwrap();
    let ev = |q: &[u8]| s.evidence_for_quote(&art, doc, q).unwrap();
    let a = s.put_node(&Claim::new("a", "h", vec![ev(b"two"), ev(b"four")], vec![])).unwrap();
    let b = s.put_node(&Claim::new("b", "h", vec![ev(b"two three")], vec![Link::new(&a)])).unwrap();
    // Evidence in another artifact does not count toward this one.
    let o = s.put_node(&Claim::new("o", "h", vec![s.evidence_for_quote(&other, b"elsewhere", b"else").unwrap()], vec![])).unwrap();
    let root = s.put_node(&Snapshot::new(vec![Link::new(&b), Link::new(&a), Link::new(&o), Link::new(&art)])).unwrap();

    let c = coverage(&s, &root, &art, doc);
    assert_eq!((c.total, c.claims), (doc.len(), 2));
    assert_eq!(c.covered, "two three".len() + "four".len());
    assert_eq!(c.gaps, vec![(18, doc.len()), (0, 4), (13, 14)]);
    assert_eq!((c.lines, c.lines_touched), (3, 2));

    // From a leaf root, only what that leaf reaches counts.
    let c = coverage(&s, &a, &art, doc);
    assert_eq!((c.covered, c.claims), (7, 1));
    // A root that is not a node (a blob, or nothing) covers nothing.
    let c = coverage(&s, &crate::id_of(b"absent"), &art, doc);
    assert_eq!((c.covered, c.claims, c.gaps.len()), (0, 0, 1));
}

